body.raw:
{
    "jsonrpc": "2.0",
    "method": "call",
    "params": {
        "service": "object",
        "method": "execute",
        "args": [
            "{{db_name}}",
            {{user_id}},
            "{{user_passwd}}",
            "ecommerce.connector",
            "external_create_credit_note",
            {
                "ecommerceId": {{ecommerce_id}},
                "companyId": {{company_id}},
                "origin": "{{origin}}",
                "invoiceId": {{sale_id}},
                "returnType": "total"  // Now invoices can only be reversed with total method
            }
        ]
    }
}
